    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

spm_by_ticker = Transactions.WHERE(
    (LOWER(transaction_type) == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="tickers", by=(ticker_symbol,)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_amount=SUM(Transactions.amount),
    total_costs=SUM(Transactions.tax) + SUM(Transactions.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    spm=IFF(total_amount > 0, (total_amount - total_costs) / total_amount * 100.0, 0.0)
)

