            (YEAR(snapshot_date) == 2023) & 
            (RANKING(by=snapshot_date.ASC()) == 1)
        ).tx_limit_monthly
    )
)

users_with_dates = Ewallet.Users.CALCULATE(
    signup_date=created_at,
    end_of_first_year=DATETIME(created_at, '1 year')
)

users_without_notifications = users_with_dates.WHERE(
    HASNOT(
        notifications.WHERE(
            (created_at >= signup_date) & (created_at <= end_of_first_year)
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=signup_date
)

